function muller  clc  A=input('Ingrese A: ');  B=input('Ingrese B: ');  %para guiar con la grafica  rango=-4:0.1:4;  plot(rango,A*sin(rango).*B.*rango.^3);  grid on;  grid minor;      display("A*sin(x) * B*x^2")  x2=input('Ingrese x2: ');  x1=input('Ingrese x1: ');  x0=input('Ingrese x0: ');    errU=input('Ingrese el error: ');   display('Iteracion: ')  i=1  %evaluo en los 3 puntos  funci2=A*sin(x2) *B*x2^3;  funci1=A*sin(x1) *B*x1^3;  funci0=A*sin(x0) *B*x0^3;  %calculo de operaciones  fx2x1 = (funci2-funci1)/(x2-x1);  fx1x0 = (funci1-funci0)/(x1-x0);  fx2x1x0 = (fx2x1-fx1x0)/(x2-x0);    a2=fx2x1x0;  a1=fx2x1 - (x2+x1)*a2;  a0=funci2 -x2*(fx2x1 - x1*a2);    %calculo discriminante  ant1=-a1+(a1^2 -4*a0*a2)^(1/2);  ant2=-a1-(a1^2 -4*a0*a2)^(1/2);    %decido en funcion de cual es mayor con valor absoluto  if (abs(ant1)>abs(ant2))    x3=(2*(a0))/(ant2)  else    x3=(2*(a0))/(ant1)  endif    %evaluo la funcion en el punto encontrado  funci3=A*sin(x3) *B*x3^3;    %calculo error  errAbs = abs(x3-x2)    display("  \n")  while (errAbs>errU)  display('Iteracion: ')  i=i+1    %actualizo las variables  funci0=funci1;  funci1=funci2;  funci2=funci3;  x0=x1;  x1=x2;  x2=x3;  %evaluo en los 3 puntos  funci2=sin(x2) *x2^3;  funci1=sin(x1) *x1^3;  funci0=sin(x0) *x0^3;  %calculo de operaciones  fx2x1 = (funci2-funci1)/(x2-x1);  fx1x0 = (funci1-funci0)/(x1-x0);  fx2x1x0 = (fx2x1-fx1x0)/(x2-x0);  a2=fx2x1x0;  a1=fx2x1 - (x2+x1)*a2;  a0=funci2 -x2*(fx2x1 - x1*a2);  %calculo discriminante  ant1=-a1+(a1^2 -4*a0*a2)^(1/2);  ant2=-a1-(a1^2 -4*a0*a2)^(1/2);    %decido en funcion de cual es mayor con valor absoluto  if (abs(ant1)>abs(ant2))    x3=(2*(a0))/(ant2)  else    x3=(2*(a0))/(ant1)  endif    %calculo error  errAbs = abs(x3-x2)    display("  \n")endwhileendfunction